from __future__ import annotations

import sys
import time
from pathlib import Path

import pytest
from starlette.applications import Starlette
from starlette.routing import WebSocketRoute
from starlette.testclient import TestClient
from starlette.websockets import WebSocketDisconnect

sys.path.insert(0, str(Path(__file__).parents[3] / "services" / "ui"))

from ui import terminal


@pytest.mark.parametrize(
    ("origin", "client", "ok"),
    [
        ("http://localhost:8000", "127.0.0.1", True),  # the app's own page
        ("http://127.0.0.1:3000", "::1", True),
        ("https://evil.example", "127.0.0.1", False),  # another site, in this machine's browser
        ("", "127.0.0.1", False),  # no origin: not a page
        ("http://localhost:8000", "192.168.1.20", False),  # another machine
    ],
)
def test_only_this_machines_pages_may_start_a_shell(origin: str, client: str, ok: bool) -> None:
    assert terminal.allowed_origin(origin, client) is ok


@pytest.fixture
def app(monkeypatch: pytest.MonkeyPatch) -> TestClient:
    monkeypatch.setattr(terminal, "LOCAL_HOSTS", {*terminal.LOCAL_HOSTS, "testclient"})  # TestClient's host
    monkeypatch.setenv("SHELL", "/bin/sh")
    return TestClient(Starlette(routes=[WebSocketRoute("/terminal/ws", terminal.shell_socket)]))


def test_a_shell_answers_over_the_socket(app: TestClient) -> None:
    with app.websocket_connect("/terminal/ws?cols=80&rows=24", headers={"origin": "http://localhost:8000"}) as ws:
        ws.send_text('{"type":"resize","cols":100,"rows":30}')
        ws.send_text("echo ghostty-$((40+2))\n")
        seen, deadline = "", time.monotonic() + 10
        while "ghostty-42" not in seen and time.monotonic() < deadline:
            seen += ws.receive_text()
    assert "ghostty-42" in seen


def test_another_site_gets_no_shell(app: TestClient) -> None:
    with (
        pytest.raises(WebSocketDisconnect),
        app.websocket_connect("/terminal/ws", headers={"origin": "https://evil.example"}) as ws,
    ):
        ws.receive_text()


def test_the_font_size_is_read_from_your_own_terminal(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.setattr(Path, "home", lambda: tmp_path)
    assert terminal.terminal_font_pt() == terminal.DEFAULT_FONT_PT  # no config: Omarchy's 9
    (tmp_path / ".config" / "kitty").mkdir(parents=True)
    (tmp_path / ".config" / "kitty" / "kitty.conf").write_text("font_family JetBrainsMono\nfont_size        10.5\n")
    assert terminal.terminal_font_pt() == 10.5
    (tmp_path / ".config" / "ghostty").mkdir()
    (tmp_path / ".config" / "ghostty" / "config").write_text("font-family = JetBrainsMono\nfont-size = 11\n")
    assert terminal.terminal_font_pt() == 11  # ghostty first


def test_the_colours_are_your_omarchy_ghostty_theme(tmp_path: Path) -> None:
    conf = tmp_path / "ghostty.conf"
    conf.write_text(
        "\n".join(
            [
                "background = #2d353b",
                "cursor-color = d3c6aa",
                "palette = 1=#e67e80",
                "palette = 12=#7fbbb3",
            ]
        )
    )
    theme = terminal.terminal_theme(conf)
    assert theme["red"] == "#e67e80"
    assert theme["brightBlue"] == "#7fbbb3"
    assert theme["cursor"] == "#d3c6aa"  # a colour without its "#" still works


def test_without_an_omarchy_theme_the_colours_are_the_repos_everforest(tmp_path: Path) -> None:
    theme = terminal.terminal_theme(tmp_path / "missing.conf")
    assert theme["background"] == "#2d353b"
    assert theme["cyan"] == "#83c092"  # all 16 colours, not only the background
    assert len(theme) == 5 + 16


def test_only_this_machine_may_frame_the_page_or_message_it() -> None:
    # a site that framed the Terminal could otherwise send its page messages, eg the
    # inline chat's paste, which types into the shell
    assert terminal.FRAME_ANCESTORS.startswith("frame-ancestors 'self' http://localhost:*")
    assert "*" not in terminal.FRAME_ANCESTORS.replace(":*", "")
    assert "if (!fromApp(event)) return;" in terminal.PAGE
    assert 'new Set(["127.0.0.1", "::1", "localhost"])' in terminal.PAGE
    # no message is handled before the check: one listener, and it starts with it
    handler = terminal.PAGE[terminal.PAGE.index('window.addEventListener("message"') :]
    assert handler.index("fromApp(event)") < handler.index("delulu-ask-paste")
    assert terminal.PAGE.count('addEventListener("message"') == 1
